// Informacje o trasach (punkt startowy, dojazd, kolor szlaku, czas
// podejścia w jedną stronę w warunkach letnich, przewyższenie) dla
// punktów Korony Gór Polski i GOT. Zebrane z niezależnych źródeł
// turystycznych (m.in. mynaszlaku.pl, kgp.info.pl, gorskim-szlakiem.pl,
// mapa-turystyczna.pl, plannawypad.pl, hasajacezajace.com, oficjalne strony
// parków narodowych) i krzyżowo sprawdzone tam, gdzie było to możliwe —
// mimo to pozostają orientacyjne (czasy i przewyższenia różnią się między
// źródłami i zależą od kondycji, pogody i wybranego wariantu trasy). Klucz
// to id punktu z src/data/points.js.
//
// Część szczytów GOT i Diademu to fizycznie te same góry co w Koronie Gór
// Polski lub GOT (np. 'sniezka', 'sniezka-kgp' i 'sniezka-diadem') — w
// takich wypadkach dane trasy są identyczne (ten sam szlak), skopiowane pod
// osobnym kluczem. Dla pozostałych, unikalnych dla danego systemu szczytów
// (Beskidy, dodatkowe partie Tatr i Bieszczadów, reszta Sudetów, mniej
// znane szczyty Diademu) dane pochodzą z osobnego researchu — dla mniej
// popularnych, słabiej opisanych szczytów są bardziej orientacyjne
// (oznaczone jako "szacunkowe").
